/// @title This module is to enter the market
module protocol::enter_market;

use std::type_name::{Self, TypeName};
use sui::event::emit;

use protocol::market::Market;
use protocol::obligation;
use protocol::app::PackageCallerCap;
use protocol::market::lending_default_emode_group;
use protocol::app::ProtocolApp;

public struct ObligationCreatedEvent has copy, drop {
    sender: address,
    market_type: TypeName,
    obligation: ID,
    emode_group: u8,
    obligation_admin_cap: ID,
}

/// @notice Create a new obligation and transfer the obligation owner cap to the sender
/// @dev the obaligation object will be a shared object, object key is the proof of ownership for the obligation
/// @param version The version control object, contract version must match with this
/// @param ctx The SUI transaction context object
#[allow(lint(self_transfer))]
public fun enter_market<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, ctx: &mut TxContext) {
    let obligation_cap = enter_market_return<MarketType>(app, market, ctx);
    transfer::public_transfer(obligation_cap, ctx.sender());
}

public fun enter_market_return<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    enter_market_inner<MarketType>(app, market, lending_default_emode_group(), ctx)
}

/// Being restrictive on who can join with emode. Consider lifting this restriction in future releases.
public fun enter_market_with_emode<MarketType>(app: &ProtocolApp, cap: &PackageCallerCap, market: &mut Market<MarketType>, emode_group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::enter_market_with_emode());
    enter_market_inner<MarketType>(app, market, emode_group, ctx)
}

fun enter_market_inner<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, emode_group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    market.assert_emode_group_exists(emode_group);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let market_type = type_name::with_defining_ids<MarketType>();
    let (obligation, obligation_cap) = obligation::new(object::id(market), emode_group, ctx);

    let obligation_id = obligation_cap.id();

    market.handle_new_obligation(obligation);

    // Emit the obligation created event
    emit(ObligationCreatedEvent {
        sender: ctx.sender(),
        market_type,
        emode_group,
        obligation: obligation_id,
        obligation_admin_cap: object::id(&obligation_cap),
    });

    obligation_cap
}

#[test_only]
public fun create_obligation_with_group<MarketType>(app: &ProtocolApp, market: &mut Market<MarketType>, group: u8, ctx: &mut TxContext): obligation::ObligationOwnerCap {
    enter_market_inner<MarketType>(app, market, group, ctx)
}

module protocol::market;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::balance::Balance;
use sui::clock::Clock;
use sui::coin::{Self, Coin};
use sui::dynamic_field;
use sui::object_table::{Self, ObjectTable};

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::{get_price, get_price_with_check};

use math::float::{Self, Decimal};
use protocol::generic_store::{Self, GenericCoinTypeStorage};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;

use protocol::asset::{Self, Asset, AssetConfig};
use protocol::error;
use protocol::interest::InterestModel;
use protocol::obligation::Obligation;
use protocol::reserve::{Self, Reserve, ReserveFlashLoan};
use protocol::value::coin_value;
use protocol::emode::{Self, EModeGroup, EModeGroupRegistry};
use protocol::adl::{new_auto_deleverage_registry, AutoDeleverageRegistry};
use protocol::liquidity_miner::{Self, LiquidityMiner};
use x_oracle::user_oracle::get_spot_price;

const DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS: u64 = 1000; // 10%
const DEFAULT_EMA_SPOT_DIFF_DENOMINATOR: u64 = 10000;

public struct MarketConfiguration has store, copy, drop {
    close_factor: Decimal,
    close_factor_bypass_min_value: u64,
}

/// Flash loan hot potato
public struct FlashLoan<phantom MarketType, phantom CoinType> {
    inner: ReserveFlashLoan<MarketType, CoinType>,
    fee: u64,
}

public fun loan_amount<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.inner.amount()
}

public fun fee<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.fee
}

// a default emode group for lending
public(package) fun lending_default_emode_group(): u8 { 0 }

public struct Market<phantom MarketType> has key, store {
    id: UID,

    assets: GenericCoinTypeStorage<Asset<MarketType>>,
    reserves: GenericCoinTypeStorage<Reserve<MarketType>>,

    /// The max price tolerance between ema and spot price. If the difference is more than this value
    /// borrow and withdraw will be rejected, default to 10% per asset.
    ema_spot_tolerance: GenericCoinTypeStorage<Decimal>,

    emode_group_registry: EModeGroupRegistry,

    obligations: ObjectTable<ID, Obligation<MarketType>>,

    liquidity_miner: LiquidityMiner<MarketType>,

    // dynamic fields:
    // - circuit_break
    // - market_config
    // - adl_registry
}

// dynamic field keys
public struct MarketConfigurationKey has copy, drop, store {}
public struct CircuitBreakKey has copy, drop, store {}
public struct ADLRegistryKey has copy, drop, store {}

// ==================== MarketConfiguration Constructor =====================
/// Create a new market configuration
public(package) fun new_market_configuration(close_factor: Decimal, close_factor_bypass_min_value: u64): MarketConfiguration {
    MarketConfiguration { close_factor, close_factor_bypass_min_value }
}

// ==================== Constructor =====================
public(package) fun new<MarketType>(
    market_config: MarketConfiguration,
    ctx: &mut TxContext,
): Market<MarketType> {
    let mut market = Market {
        id: object::new(ctx),

        emode_group_registry: emode::new_e_mode_registry(ctx),

        assets: generic_store::new(ctx),
        reserves: generic_store::new(ctx),

        ema_spot_tolerance: generic_store::new(ctx),

        obligations: object_table::new(ctx),
        liquidity_miner: liquidity_miner::new_liquidity_miner(ctx),
    };

    dynamic_field::add(&mut market.id, MarketConfigurationKey {}, market_config);
    dynamic_field::add(&mut market.id, CircuitBreakKey {}, false);
    dynamic_field::add(&mut market.id, ADLRegistryKey {}, new_auto_deleverage_registry(ctx));

    market
}

// admin
public(package) fun emode_registry_mut<MarketType>(self: &mut Market<MarketType>): &mut EModeGroupRegistry {
    &mut self.emode_group_registry
}

public(package) fun trigger_circuit_break<MarketType>(self: &mut Market<MarketType>) {
    let is_circuit_break = dynamic_field::borrow_mut(&mut self.id, CircuitBreakKey {});

    assert!(!*is_circuit_break, error::already_under_circuit_break());
    *is_circuit_break = true;
}

public(package) fun discharge_circuit_break<MarketType>(self: &mut Market<MarketType>) {
    let is_circuit_break = dynamic_field::borrow_mut(&mut self.id, CircuitBreakKey {});

    assert!(*is_circuit_break, error::not_under_circuit_break());
    *is_circuit_break = false;
}

public(package) fun update_market_config<MarketType>(self: &mut Market<MarketType>, config: MarketConfiguration) {
    *dynamic_field::borrow_mut(&mut self.id, MarketConfigurationKey {}) = config;
}

public(package) fun adl_registry_mut<MarketType>(self: &mut Market<MarketType>): &mut AutoDeleverageRegistry {
    dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {})
}

// =============== Public Getter Functions ==============

public fun assert_emode_group_exists<MarketType>(self: &Market<MarketType>, group: u8) {
    self.emode_group_registry.ensure_group_exists(group)
}

public fun emode_registry<MarketType>(self: &Market<MarketType>): &EModeGroupRegistry {
    &self.emode_group_registry
}

public(package) fun supported_assets<MarketType>(self: &Market<MarketType>): vector<TypeName> {
    self.assets.keys()
}

public(package) fun has_circuit_break_triggered<MarketType>(self: &Market<MarketType>): bool {
    *dynamic_field::borrow(&self.id, CircuitBreakKey {})
}

public(package) fun market_config<MarketType>(self: &Market<MarketType>): &MarketConfiguration {
    dynamic_field::borrow(&self.id, MarketConfigurationKey {})
}

public(package) fun adl_registry<MarketType>(self: &Market<MarketType>): &AutoDeleverageRegistry {
    dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {})
}

public(package) fun asset_by_type<MarketType>(
    self: &Market<MarketType>,
    name: TypeName,
): &Asset<MarketType> {
    self.assets.load_by_type<Asset<MarketType>>(name)
}

public(package) fun reserve_by_type<MarketType>(
    self: &Market<MarketType>,
    name: TypeName,
): &Reserve<MarketType> {
    self.reserves.load_by_type<Reserve<MarketType>>(name)
}

public fun exchange_rate<MarketType>(self: &Market<MarketType>, coin_type: TypeName): Decimal {
    self.reserve_by_type<MarketType>(coin_type).exchange_rate()
}

public fun borrow_obligation<MarketType>(
    self: &Market<MarketType>,
    obligation_id: ID,
): &Obligation<MarketType> {
    self.obligations.borrow(obligation_id)
}

// =============== Admin Functions ==============
public(package) fun market_asset_borrow_mut<MarketType, CoinType>(
    self: &mut Market<MarketType>,
): &mut Asset<MarketType> {
    self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>())
}

public(package) fun set_ema_spot_tolerance<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    tolerance_bps: u64
) {
    assert!(tolerance_bps < DEFAULT_EMA_SPOT_DIFF_DENOMINATOR, error::invalid_params_error());

    let tolerance = math::float::from_quotient(tolerance_bps, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR);

    let t = self.ema_spot_tolerance.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    *t = tolerance;
}

/// Take revenue from market reserves
public(package) fun take_revenue<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    amount: u64,
    ctx: &mut TxContext,
): Coin<CoinType> {
    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    let balance = reserve::take_revenue<MarketType, CoinType>(reserve, amount);
    coin::from_balance(balance, ctx)
}

// ================== Internal Update Functions ================
public(package) fun onboard_new_asset<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    interest_model: InterestModel,
    borrow: AssetConfig,
    now: u64,
    ctx: &mut TxContext,
) {
    assert!(!self.assets.supports<Asset<MarketType>, CoinType>(), error::asset_already_onboarded());

    let new_asset = asset::new<MarketType>(interest_model, borrow, ctx);
    self.assets.store<Asset<MarketType>, CoinType>(new_asset);

    let reserve = reserve::new<MarketType, CoinType>(ctx, now);
    self.reserves.store<Reserve<MarketType>, CoinType>(reserve);

    self.ema_spot_tolerance.store<Decimal, CoinType>(float::from_quotient(DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR));

    self.liquidity_miner.support_coin<MarketType, CoinType>(ctx);
}

public(package) fun handle_new_obligation<MarketType>(
    self: &mut Market<MarketType>,
    obligation: Obligation<MarketType>,
) {
    self.obligations.add(object::id(&obligation), obligation);
}

public(package) fun borrow_liquidity_mining<MarketType>(self: &Market<MarketType>): &LiquidityMiner<MarketType> {
    &self.liquidity_miner
}

public(package) fun borrow_liquidity_mining_mut<MarketType>(self: &mut Market<MarketType>): &mut LiquidityMiner<MarketType> {
    &mut self.liquidity_miner
}

public(package) fun handle_mint<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation: ID,
    coin: Coin<CoinType>,
    now: u64,
): (u64, u64) {
    assert!(coin.value() != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();
    let deposit_amount = coin.value();

    let asset = self.assets.load_mut_by_type(name);
    assert!(!asset.deposit_paused(), error::deposit_paused_for_asset());

    let asset_config = asset.asset_config();

    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset_config, asset.interest_model(), now);

    // technically should be in stable coin value, but keep it this way for now
    assert!(
        !reserve.deposit_limit_breached<MarketType>(
            deposit_amount,
            asset_config.max_deposit_amount(),
        ),
        error::market_deposit_limit_exceeded(),
    );

    let ctoken = reserve.mint_ctokens(coin);
    let ctoken_amount = ctoken.value();

    // now handle obligation related
    let obligation = self.obligations.borrow_mut(obligation);
    assert!(
        obligation.market_id() == self.id.uid_as_inner(),
        error::obligation_from_different_market(),
    );
    obligation.deposit_ctoken<MarketType, CoinType>(ctoken);

    // update rate limit deposit 
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().reduce_outflow(now, deposit_amount);

    (ctoken_amount, obligation.ctoken_amount_by_coin(name))
}

public(package) fun handle_withdraw<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    ctoken_amount: u64,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, u64) {
    assert!(ctoken_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_by_type(name);
    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());


    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // refresh all interest
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
    refresh_obligation_assets_interest<MarketType>(&self.assets, emode_group, &mut self.reserves, obligation, now);

    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
    let ctokens_left = obligation.ctoken_amount_by_coin(name);

    // TODO: if the asset is not collateral, skip obligation safety check
    let is_obligation_safe = is_obligation_safe(
        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
        &self.reserves,
        &self.ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    let reserve = self.reserves.load_mut_by_type(name);
    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));

    // rate limit deposit withdraw
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
    emode.borrow_mut_deposit_limiter().add_outflow(
        now,
        deposit.value(),
    );

    // update adl

    // use ceiling, slighly more 
    let total_deposit = reserve.total_deposit_plus_interest().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);



    (deposit.into_coin(ctx), ctokens_left)
}

public(package) fun handle_borrow<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    borrow_amount: u64,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
): (Balance<CoinType>, Decimal, Decimal) {
    assert!(borrow_amount != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();



    // basic checks
    let asset = self.assets.load_mut_by_type(name);
    assert!(!asset.borrow_paused(), error::borrow_paused_for_asset());



    // load data for later checks
    let asset_config = asset.asset_config();
    let min_borrow_amount = asset_config.min_borrow_amount();
    let asset_max_borrow_amount = asset_config.max_borrow_amount();


    let obligation = self
        .obligations
        .borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
    let asset_name = type_name::with_defining_ids<CoinType>();

    // make sure the outflow is rate limited
    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), asset_name);
    let emode_max_borrow_amount = emode.borrow().max_borrow_amount();
    emode.borrow_mut_borrow_limiter().add_outflow(now, borrow_amount);

    let obligation_old_total_borrow_amount = if (!obligation.has_debt(name)) { float::zero() } else { obligation.debt(name).unsafe_debt_amount() };

    // refresh only borrow, practically, obligation owner can borrow a bit more due to collateral interest
    refresh_obligation_borrow_interest_with_new_borrow<MarketType>(name, &self.assets, &mut self.reserves, obligation, now);

    // update obligation
    let borrow_index = self.reserves.load_by_type(name).borrow_index().value();

    obligation.try_borrow_asset<MarketType, CoinType>(borrow_amount, borrow_index);
    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);

    // interest updated, should be up to date
    let obligation_new_total_borrow_amount = obligation.debt(name).unsafe_debt_amount();
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());


    // make sure the emode group borrow limit is not breached
    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_total_borrow_amount, obligation_new_total_borrow_amount);
    assert!(emode_group_total_borrow.le(math::float::from(emode_max_borrow_amount)), error::emode_borrow_limit_exceeded());

    let is_obligation_safe = is_obligation_safe(
        emode_group,
        &self.reserves,
        &self.ema_spot_tolerance,

        self.obligations.borrow(obligation_id),
        coin_decimals_registry,
        x_oracle,
        clock,
    );
    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());

    // perform borrow
    let reserve = self.reserves.load_mut_by_type(name);
    let balance = reserve.borrow_amount<MarketType, CoinType>(borrow_amount);

    assert!((*reserve.debt()).ceil() <= asset_max_borrow_amount, error::market_borrow_limit_exceeded());

    (balance, borrow_index, obligation_new_total_borrow_amount)
}

public(package) fun handle_repay<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    mut coin: Coin<CoinType>,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, Decimal, Decimal) {
    assert!(coin.value() != 0, error::no_zero_amount());

    let name = type_name::with_defining_ids<CoinType>();

    let asset = self.assets.load_mut_by_type(name);
    let min_borrow_amount = asset.asset_config().min_borrow_amount();

    let reserve = accrue_interest<MarketType>(name, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());


    let obligation_old_borrow_amount = obligation.debt(name).unsafe_debt_amount();


    let borrow_index = reserve.borrow_index().value();
    let residule = obligation.repay_debt<MarketType, CoinType>(coin.value(), borrow_index);
    obligation.enforce_post_borrow_repay_invariant<MarketType, CoinType>(min_borrow_amount);

    // interest updated, should be up to date
    let obligation_new_borrow_amount = if (obligation.has_debt(name)) obligation.debt(name).unsafe_debt_amount() else float::zero();

    let refund = coin.split(residule, ctx);

    let emode_group_id = obligation.emode_group();

    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
    let emode_group_total_borrow = emode_group.update_asset_borrow(name, obligation_old_borrow_amount, obligation_new_borrow_amount);

    let emode = emode_group.borrow_emode_mut(name);
    emode.borrow_mut_borrow_limiter().reduce_outflow(now, coin.value());


    reserve.repay_amount(coin);

    // try stop adl, if there is one on going
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
    // use ceiling, slighly more 
    adl.try_stop_borrow_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), emode_group_id, emode_group_total_borrow.ceil());

    (refund, borrow_index, obligation_new_borrow_amount)
}

public(package) fun handle_liquidation<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let MarketConfiguration { close_factor, close_factor_bypass_min_value } = *self.market_config();

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    let emode_group_id = obligation.emode_group();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
    let collateral_setting = emode_group.borrow_emode(collateral_name).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let asset = self.assets.load_mut_by_type(collateral_name);
    assert!(!asset.liquidation_paused(), error::liquidation_paused_for_asset());

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::none(),
        liquidation_incentive: collateral_setting.liquidation_incentive(),
        liquidation_revenue_factor: self.assets.load_by_type(type_name::with_defining_ids<CollateralType>()).asset_config().liquidation_fee_rate(),
        close_factor,
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

public(package) fun handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    let emode_group_id = obligation.emode_group();
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    let collateral_setting = emode_group.borrow_emode(collateral_type).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();


    let adl_registry = dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {});
    let timelock = *adl_registry.get_borrow_deleverage(debt_type, emode_group_id);

    let asset = self.assets.load_mut_by_type(debt_type);
    accrue_interest<MarketType>(debt_type, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_debt = (*self.reserves.load_by_type(debt_type).debt()).floor();
    let debt_params = timelock.inner();
    debt_params.ensure_limit_breached(total_debt);


    let activation_time = timelock.get_secs_since_activation(clock);
    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(debt_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: debt_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: debt_params.close_factor(),
        close_factor_bypass_min_value,
    };



    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

public(package) fun handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let collateral = type_name::with_defining_ids<CollateralType>();

    // load the time locked adl params
    let adl_registry = self.adl_registry<MarketType>();
    let timelock = *adl_registry.get_collateral_deleverage(collateral);

    // refresh obligation
    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    // obtain the emode group
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    // make sure the Collateral Type is indeed a collateral, otherwise revert
    let collateral_setting = emode_group.borrow_emode(collateral).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();

    // force interest update for the collateral asset
    let asset = self.assets.load_mut_by_type(collateral);
    accrue_interest<MarketType>(collateral, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_deposit = self.reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().floor();
    let collateral_params = timelock.inner();
    collateral_params.ensure_limit_breached(total_deposit);
    let activation_time = timelock.get_secs_since_activation(clock);

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(collateral_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: collateral_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: collateral_params.close_factor(),
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

fun try_stop_collateral_deleverage<MarketType, CollateralType>(id: &mut UID, reserves: &GenericCoinTypeStorage<Reserve<MarketType>>, collateral: TypeName) {
    let total_deposit = reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().ceil();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(id, ADLRegistryKey {});
    adl.try_stop_collateral_deleverage<CollateralType>(type_name::with_defining_ids<MarketType>(), total_deposit);
}

fun try_stop_borrow_deleverage<MarketType, DebtType>(market_id: &mut UID, emode_group_id: u8, emode_group: &EModeGroup, debt_type: TypeName) {
    let total_borrow = emode_group.borrow_amount(debt_type).floor();
    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(market_id, ADLRegistryKey {});
    adl.try_stop_borrow_deleverage<DebtType>(type_name::with_defining_ids<MarketType>(), emode_group_id, total_borrow);
}

fun liquidation_inner<MarketType, DebtType, CollateralType>(
    id: &mut UID,

    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &mut EModeGroup,

    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,

    obligation: &mut Obligation<MarketType>,
    liquidation_params: &LiquidationParams,

    mut available_repay_coin: Coin<DebtType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    now: u64,

    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    assert!(available_repay_coin.value() != 0, error::liquidation_zero_repay());

    let debt_name = type_name::with_defining_ids<DebtType>();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let obligation_old_borrow_amount = obligation.debt(debt_name).unsafe_debt_amount();

    // update all assets interest in the obligation
    refresh_obligation_assets_interest(assets, emode_group, reserves, obligation, now);

    ensure_liquidate_borrow_allowed<MarketType, DebtType>(
        liquidation_params,
        obligation,
        emode_group,
        reserves,
        coin_decimals_registry,
        available_repay_coin.value(),
        x_oracle,
        clock,
    );

    // calculate how much collateral can be seized first
    let obligation_latest_borrow_amount = obligation.debt(debt_name)
        .unsafe_debt_amount()
        // repay a bit more
        .ceil();
    let mut refund_coins = if (obligation_latest_borrow_amount < available_repay_coin.value()) {
        let refund_amount = available_repay_coin.value() - obligation_latest_borrow_amount;
        available_repay_coin.split(refund_amount, ctx)
    } else {
        sui::coin::zero(ctx)
    };

    // NOTE: disable rate limit

    let collateral_reserve = reserves.load_mut_by_type(type_name::with_defining_ids<CollateralType>());
    let exchange_rate = collateral_reserve.exchange_rate<MarketType>(); 

    let mut seized_ctokens = liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
        exchange_rate,
        liquidation_params.liquidation_incentive,
        available_repay_coin.value(),
        emode_group.get_oracle_base_token(),
        x_oracle,
        coin_decimals_registry,
        clock,
    );

    // check if we need to refund debt coin because there might not be enough ctoken to be liquidated
    let total_ctokens = obligation.ctoken_amount_by_coin(type_name::with_defining_ids<CollateralType>());
    if (total_ctokens < seized_ctokens) {
        let expected_repay_amount = float::from_quotient(total_ctokens, seized_ctokens)
            .mul_u64(available_repay_coin.value())
            // repay a bit more
            .ceil();
        let refund = available_repay_coin.value() - expected_repay_amount;

        refund_coins.join(available_repay_coin.split(refund, ctx));
        seized_ctokens = total_ctokens;
    };

    // at this stage, even if there is residual, it should be a very small amount, let the protocol consume the residual
    let _residual = obligation.unsafe_repay_debt_only<MarketType, DebtType>(available_repay_coin.value());

    let ctoken_balance = obligation.withdraw_ctokens<MarketType, CollateralType>(seized_ctokens);
    let ctoken_balance_amount = ctoken_balance.value();
    let refund_balance = collateral_reserve.liquidate_ctokens<MarketType, CollateralType>(
        ctoken_balance.into_coin(ctx),
        liquidation_params.liquidation_revenue_factor,
    );

    let obligation_new_borrow_amount = if (!obligation.has_debt(debt_name)) { float::zero() } else { obligation.debt(debt_name).unsafe_debt_amount() };
    emode_group.update_asset_borrow(debt_name, obligation_old_borrow_amount, obligation_new_borrow_amount);

    let debt_reserve = reserves.load_mut_by_type(debt_name);
    debt_reserve.repay_amount<MarketType, DebtType>(available_repay_coin);

    try_stop_borrow_deleverage<MarketType, DebtType>(id, obligation.emode_group(), emode_group, debt_name);
    try_stop_collateral_deleverage<MarketType, CollateralType>(id, reserves, collateral_name);

    (refund_balance.into_coin(ctx), refund_coins, ctoken_balance_amount)
}

public(package) fun borrow_flash_loan<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    emode_group: u8,
    amount: u64,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());

    assert!(!asset.flash_loan_paused(), error::flash_loan_paused_for_asset());
    assert!(!asset.flash_loan_ongoing(), error::flash_loan_ongoing());

    asset.flash_loan_triggered<MarketType>();

    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());

    let emode = self.emode_group_registry.borrow_emode_group(emode_group).borrow_emode(type_name::with_defining_ids<CoinType>());
    let flash_loan_fee_rate = emode.flash_loan().fee_rate();

    let fee = flash_loan_fee_rate.int_mul(amount);
    assert!(fee != 0, error::reserve_flash_loan_fee_too_small());

    let (balance, inner) = reserve.borrow_flash_loan(amount);
    (balance.into_coin(ctx), FlashLoan<MarketType, CoinType> { inner, fee })
}

public(package) fun repay_flash_loan<MarketType, CoinType>(
    self: &mut Market<MarketType>,

    mut coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    referral: &mut protocol::referral::Referral,
    mut maybe_referral_code: Option<String>,

    ctx: &mut TxContext
) {
    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());

    assert!(asset.flash_loan_ongoing(), error::flash_loan_not_ongoing());
    asset.flash_loan_finished<MarketType>();

    let FlashLoan { inner, fee } = loan;
    assert!(coin.value() == inner.amount() + fee, error::reserve_flash_loan_not_paid_enough());

    let mut fee_coin = coin.split(fee, ctx);

    if (maybe_referral_code.is_some()) {
        let referral_code = maybe_referral_code.extract();
        fee_coin = referral.track_flash_loan_usage(
            fee_coin,
            referral_code,
            ctx.sender(),
            ctx,
        );

        // no free ride after rebate
        assert!(fee_coin.value() != 0, error::reserve_flash_loan_fee_too_small());
    };

    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    reserve.repay_flash_loan(inner, coin, fee_coin);
}

fun refresh_obligation_assets_interest<MarketType>(
    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    emode_group: &EModeGroup,
    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
    obligation: &mut Obligation<MarketType>,
    now: u64,
) {
    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);

    // collateral
    let asset_types = obligation.deposit_types();

    let (mut i, n) = (0, asset_types.length());

    while (i < n) {
        let name = asset_types[i];

        let asset = assets.load_by_type(name);
        let collateral_settings = emode_group.borrow_emode(name).collateral();

        // update index first, since it's not used after this point
        i = i + 1;

        // cannot be collateral, ignore
        if (!collateral_settings.can_be_collateral()) { continue };

        accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
    };
}

fun refresh_obligation_borrow_interest_with_new_borrow<MarketType>(
    maybe_new_borrow_coin_type: TypeName,
    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
    obligation: &mut Obligation<MarketType>,
    now: u64,
) {

    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);

    if (obligation.has_debt(maybe_new_borrow_coin_type)) { return };

    let asset = assets.load_by_type(maybe_new_borrow_coin_type);
    accrue_interest(maybe_new_borrow_coin_type, reserves, asset.asset_config(), asset.interest_model(), now);
}

fun refresh_obligation_borrow_interest<MarketType>(
    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
    obligation: &mut Obligation<MarketType>,
    now: u64,
) {
    let asset_types = obligation.debt_types();

    let (mut i, n) = (0, asset_types.length());

    while (i < n) {
        let name = asset_types[i];

        let asset = assets.load_by_type(name);

        let reserve = accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
        obligation.accrue_interest(name, reserve.borrow_index().value());

        i = i + 1;
    };
}

/// Make sure the caller has refresh all obligation debt and collateral interest before calling this method
fun ensure_liquidate_borrow_allowed<MarketType, DebtType>(
    liquidation_params: &LiquidationParams,

    obligation: &Obligation<MarketType>,

    emode_group: &EModeGroup,

    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    liquidator_repay_amount: u64,

    x_oracle: &XOracle,

    clock: &Clock,
) {
    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
    let (weighted_debts_value, debts_total_value) = debts_value_usd_for_liquidation(
        emode_group,
        reserves,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    let (collateral_weighted_value, collateral_total_value) = collaterals_usd_for_liquidation(
        emode_group,
        reserves,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    // triggering condition: 
    // user_ltv > liquidation_ltv
    if (liquidation_params.liquidation_ltv_threshold_override.is_some()) {
        let liquidation_ltv = *liquidation_params.liquidation_ltv_threshold_override.borrow();
        let user_ltv = weighted_debts_value.div(collateral_total_value);
        assert!(
            user_ltv.gt(liquidation_ltv),
            error::liquidation_obligation_still_safe(),
        );
    } else {
        // user_ltv = weighted_debts_value / collateral_total_value
        // liquidation_ltv = collateral_weighted_value / collateral_total_value
        // user_ltv > liquidation_ltv
        //    weighted_debts_value / collateral_total_value > collateral_weighted_value / collateral_total_value
        //    weighted_debts_value / collateral_weighted_value > liquidation_ltv_threshold
        //    weighted_debts_value > collateral_weighted_value * liquidation_ltv_threshold
        assert!(
            weighted_debts_value.gt(collateral_weighted_value),
            error::liquidation_obligation_still_safe(),
        );
    };

    // Note that the close factor is enforce ONLY when the obligation is not close to bad debt
    let bad_debt_close_factor_bypass_threshold = float::from_quotient(101, 100);
    let bad_debt_threshold = bad_debt_close_factor_bypass_threshold.mul(debts_total_value);

    if (collateral_total_value.le(bad_debt_threshold)) {
        // This means the obligation is close to bad debt, allow close whatever is passed
        // close factor effectively equals to 1.
        return
    };

    let target_debt_type = type_name::with_defining_ids<DebtType>();

    let debt_balance = obligation.debt(target_debt_type).unsafe_debt_amount();
    let debt_value = coin_value(
        get_price(x_oracle, target_debt_type, emode_group.get_oracle_base_token(), clock),
        debt_balance,
        coin_decimals_registry.decimals(target_debt_type)
    )
        // this is tricky, because it is using ceiling, this mean if the debt value is say 9.8, the ceiling is 10
        .ceil();

    // below min usd for close factor enforcement
    if (debt_value <= liquidation_params.close_factor_bypass_min_value) { return };

    let max_debt_amount = debt_balance.mul(liquidation_params.close_factor);
    assert!(
        math::float::from(liquidator_repay_amount).le(max_debt_amount),
        error::liquidation_close_factor_exceeded(),
    );
}

fun accrue_interest<MarketType>(
    coin_type: TypeName,
    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
    asset: &AssetConfig,
    interest_model: &InterestModel,
    now: u64,
): &mut Reserve<MarketType> {
    let reserve = reserves.load_mut_by_type(coin_type);

    let interest_rate = interest_model.calc_interest(reserve.util_rate());
    reserve.accrue_interest(asset.repay_fee_rate(), interest_rate, now);

    reserve
}

// calculate the actual repay amount, actual liquidate amount, actual market amount
fun liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
    exchange_rate: Decimal,
    liquidation_incentive: Decimal,
    actual_repay_amount: u64,

    oracle_base_token: x_oracle::x_oracle::BaseToken,
    x_oracle: &XOracle,

    coin_registry: &CoinDecimalsRegistry,
    clock: &Clock,
): u64 {
    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let price_borrowed = get_spot_price(x_oracle, debt_type, oracle_base_token, clock);
    let price_collateral = get_spot_price(x_oracle, collateral_type, oracle_base_token, clock);

    let actual_repay_amount = float::from(actual_repay_amount);

    let debt_decimals = math::u64::pow10_u64(coin_registry.decimals(debt_type));
    let collateral_decimals = math::u64::pow10_u64(coin_registry.decimals(collateral_type));

    /*
     * Get the exchange rate and calculate the number of collateral tokens to seize:
     *  seizeAmount = (actualRepayAmount + actualRepayAmount * liquidationIncentive) * priceBorrowed / priceCollateral
     *  seizeTokens = seizeAmount / exchangeRate
     */
    let incentivised_borrow = actual_repay_amount.add(actual_repay_amount.mul(
        liquidation_incentive,
    ));
    // ignoreing decimal calculation as they will be cancelled out
    let incentivised_borrow_usd = incentivised_borrow.mul(price_borrowed).div_u64(debt_decimals);
    let seize_collaterals = incentivised_borrow_usd.div(price_collateral).mul_u64(collateral_decimals);

    let seize_ctokens = seize_collaterals.div(exchange_rate);

    assert!(
        seize_ctokens.lt(float::from(std::u64::max_value!())),
        error::invariant_seize_tokens_crazy_big(),
    );

    // only take the tecnnically possible amount
    seize_ctokens.floor()
}

